namespace Win1223; internal static class Logger{static readonly object L=new(); static string F=>System.IO.Path.Combine(Config.LogDir,$"{System.DateTime.Now:yyyy-MM-dd}.log"); static void W(string l,string m){lock(L){System.IO.Directory.CreateDirectory(Config.LogDir);System.IO.File.AppendAllText(F,$"{System.DateTime.Now:HH:mm:ss} [{l}] {m}{System.Environment.NewLine}");}} public static void Info(string m)=>W("INFO",m); public static void Error(string m)=>W("ERROR",m);}